  ('spell.soothe', 'Abrandar', 'Soothe', 'Calmar heridas', 'Cura uma criatura voluntária e fortalece temporariamente suas defesas contra efeitos mentais.', 'Heals a willing creature and temporarily strengthens its defenses against mental effects.', 'Cura a una criatura voluntaria y fortalece temporalmente sus defensas contra efectos mentales.', 1, FALSE, FALSE, ARRAY['occult']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 314, '{"heightened":null,"needs_review":false}'::jsonb),
