  ('spell.acid_grip', 'Aperto Ácido', 'Acid Grip', 'Agarre ácido', 'Uma garra mágica causa dano de ácido e pode mover o alvo conforme o salvamento de Reflexos.', 'A magical claw deals acid damage and can move the target based on its Reflex save.', 'Una garra mágica causa daño de ácido y puede mover al objetivo según su salvación de Reflejos.', 2, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 316, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.electric_arc', 'Arco Elétrico', 'Electric Arc', 'Arco eléctrico', 'Um arco de eletricidade atinge uma ou duas criaturas com um salvamento básico de Reflexos.', 'An arc of electricity strikes one or two creatures with a basic Reflex save.', 'Un arco de electricidad golpea a una o dos criaturas con una salvación básica de Reflejos.', 1, FALSE, FALSE, ARRAY['arcane', 'primal']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 316, '{"heightened":null,"needs_review":false}'::jsonb),
