  ('spell.player_core_2.oracle.revelation_tempest_explos_o_trov_o', 'Explosão-Trovão', 'Thunderburst', 'Estallido de trueno', 'Uma rajada de ar e trovão causa dano contundente e sônico em uma área.', 'Additional revelation spell of the Thunderburst mystery.', 'Conjuro de revelación adicional del misterio Estallido de trueno.', 3, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Oráculo', 'Incomum', 'Foco']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 265, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.oracle.revelation_tempest_forma_de_tempestade', 'Forma de Tempestade', 'Storm Form', 'Forma de tormenta', 'Seu corpo se torna ar, água ou névoa para atravessar o campo de batalha.', 'Additional revelation spell of the Storm Form mystery.', 'Conjuro de revelación adicional del misterio Forma de tormenta.', 6, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Oráculo', 'Incomum', 'Foco']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 265, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.oracle.revelation_life_adiar_afli_o', 'Adiar Aflição', 'Delay Affliction', 'Retrasar aflicción', 'Você suspende temporariamente uma aflição e restaura parte da vitalidade do alvo.', 'Additional revelation spell of the Delay Affliction mystery.', 'Conjuro de revelación adicional del misterio Retrasar aflicción.', 3, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Oráculo', 'Incomum', 'Foco']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 265, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.oracle.revelation_life_forma_vivificante', 'Forma Vivificante', 'Vivifying Form', 'Forma vivificante', 'Você se torna um farol de energia vital que cura aliados e fere mortos-vivos.', 'Additional revelation spell of the Vivifying Form mystery.', 'Conjuro de revelación adicional del misterio Forma vivificante.', 6, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Oráculo', 'Incomum', 'Foco']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 265, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.faiths_flamekeeper', 'Avivar o Coração', 'Stoke the Heart', 'Avivar el Corazón', 'O alvo recebe +2 de bônus de estado nas jogadas de dano; aumenta em 1 a cada dois ranques elevados.', 'The target gains a +2 status bonus to damage rolls, increasing by 1 for every two heightened ranks.', 'El objetivo obtiene +2 de bonificador de estado al daño, que aumenta en 1 cada dos rangos aumentados.', 1, TRUE, FALSE, ARRAY['divine']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.wilding_steward', 'Palavra dos Ermos', 'Wilding Word', 'Palabra Salvaje', 'Protege você da hostilidade do alvo; animais, fungos e plantas sofrem penalidade adicional no salvamento.', 'Hinders the target from harming you; animals, fungi, and plants take an additional penalty to the save.', 'Dificulta que el objetivo te dañe; animales, hongos y plantas sufren una penalización adicional a la salvación.', 1, TRUE, FALSE, ARRAY['primal']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.the_inscribed_one', 'Discernir Segredos', 'Discern Secrets', 'Discernir Secretos', 'Permite ao alvo Buscar, Recordar Conhecimento ou Sentir Motivação como ação livre com +1 de bônus de estado.', 'Lets the target Seek, Recall Knowledge, or Sense Motive as a free action with a +1 status bonus.', 'Permite al objetivo Buscar, Recordar Saber o Percibir Motivación como acción libre con +1 de bonificador de estado.', 1, TRUE, FALSE, ARRAY['arcane']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.the_resentment', 'Mau-Olhado', 'Evil Eye', 'Mal de Ojo', 'Em uma falha de Vontade, o alvo fica enjoado 1, ou enjoado 2 em falha crítica, enquanto o hex for sustentado.', 'On a failed Will save, the target becomes sickened 1, or sickened 2 on a critical failure, while the hex is sustained.', 'Con una salvación de Voluntad fallida, el objetivo queda mareado 1, o mareado 2 con fallo crítico, mientras se mantenga el maleficio.', 1, TRUE, FALSE, ARRAY['occult']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.spinner_of_threads', 'Tocar o Destino', 'Nudge Fate', 'Tocar el Destino', 'Concede retroativamente +1 de bônus de estado quando isso melhorar em um grau um teste recém-falhado do alvo.', 'Retroactively grants a +1 status bonus when it improves the target''s newly failed check by one degree.', 'Concede retroactivamente +1 de bonificador de estado cuando mejora en un grado una prueba recién fallida del objetivo.', 1, TRUE, FALSE, ARRAY['occult']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 375, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.silence_in_snow', 'Gelo Duradouro', 'Clinging Ice', 'Hielo Persistente', 'Causa dano de frio e penalidade de circunstância nas Velocidades do alvo enquanto for sustentado.', 'Deals cold damage and imposes a circumstance penalty to the target''s Speeds while sustained.', 'Inflige daño de frío e impone una penalización de circunstancia a las Velocidades del objetivo mientras se mantenga.', 1, TRUE, FALSE, ARRAY['primal']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core.witch.starless_shadow', 'Mortalha da Noite', 'Shroud of Night', 'Sudario de la Noche', 'Uma falha de Vontade envolve o alvo em escuridão, fazendo luz forte contar como luz fraca e criaturas ficarem ocultadas.', 'A failed Will save shrouds the target in darkness, making bright light count as dim light and creatures concealed.', 'Una salvación de Voluntad fallida cubre al objetivo de oscuridad, haciendo que la luz brillante cuente como tenue y las criaturas queden ocultas.', 1, TRUE, FALSE, ARRAY['occult']::text[], 'one-action', NULL, NULL, NULL, NULL, ARRAY['Bruxo', 'Incomum', 'Sortilégio', 'Truque']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 374, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.champion.shields_of_the_spirit', 'Escudos do Espírito', 'Shields of the Spirit', 'Escudos del espíritu', 'Você Ergue seu Escudo e concede +1 de bônus de estado na CA aos aliados em sua aura; atacantes sofrem dano espiritual.', 'You Raise your Shield and grant allies in your aura a +1 status bonus to AC; attackers take spirit damage.', 'Alzas tu escudo y otorgas a los aliados en tu aura un bonificador de estado +1 a la CA; los atacantes sufren daño espiritual.', 1, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Campeão', 'Concentração', 'Espírito', 'Foco', 'Santificado']::text[], 'uncommon', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 256, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.champion.lay_on_hands', 'Imposição de Mãos', 'Lay on Hands', 'Imposición de manos', 'Cura uma criatura viva voluntária ou fere uma criatura morta-viva com vitalidade, concedendo proteção temporária ao aliado curado.', 'Heals a willing living creature or harms an undead creature with vitality, granting temporary protection to a healed ally.', 'Cura a una criatura viva voluntaria o daña a una criatura no muerta con vitalidad, otorgando protección temporal al aliado curado.', 1, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Campeão', 'Cura', 'Foco', 'Manuseio', 'Vitalidade']::text[], 'uncommon', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 256, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.champion.touch_of_the_void', 'Toque do Vazio', 'Touch of the Void', 'Toque del vacío', 'Cura uma criatura morta-viva voluntária ou causa dano eversivo a uma criatura viva, com penalidade de CA em uma falha.', 'Heals a willing undead creature or deals void damage to a living creature, with an AC penalty on a failure.', 'Cura a una criatura no muerta voluntaria o inflige daño de vacío a una criatura viva, con penalización a la CA en un fallo.', 1, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Campeão', 'Eversão', 'Foco', 'Manuseio']::text[], 'uncommon', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 256, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.champion.spectral_advance', 'Avanço Espectral', 'Spectral Advance', 'Avance espectral', 'Move-se em forma espiritual sem ativar reações, ignorando terreno difícil e recebendo resistência durante o deslocamento.', 'Move in spiritual form without triggering reactions, ignoring difficult terrain and gaining resistance during the movement.', 'Te mueves en forma espiritual sin activar reacciones, ignoras terreno difícil y obtienes resistencia durante el movimiento.', 5, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Campeão', 'Concentração', 'Espírito', 'Foco', 'Polimorfia']::text[], 'uncommon', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 257, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.player_core_2.champion.heros_defiance', 'Desafio do Herói', 'Hero''s Defiance', 'Desafío del héroe', 'Quando um ataque reduziria você a 0 PV, recupera vida antes do dano e pode evitar cair inconsciente ou morrendo.', 'When an attack would reduce you to 0 HP, regain health before damage and may avoid becoming unconscious or dying.', 'Cuando un ataque te reduciría a 0 PG, recuperas vida antes del daño y puedes evitar quedar inconsciente o moribundo.', 10, FALSE, TRUE, ARRAY['divine']::text[], 'two-actions', NULL, NULL, NULL, NULL, ARRAY['Campeão', 'Concentração', 'Cura', 'Foco', 'Vitalidade']::text[], 'uncommon', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 257, '{"heightened":null,"needs_review":false}'::jsonb),
