  ('ritual.animate_object', 'Animar Objeto', 'Animate Object', 'Animar objeto', 'Transforma um objeto em uma criatura animada; um resultado superior pode permitir controlá-la como lacaio.', 'Transforms an object into an animated creature; a superior result can allow it to be controlled as a minion.', 'Transforma un objeto en una criatura animada; un resultado superior puede permitir controlarla como esbirro.', 2, '1 dia', NULL, NULL, ARRAY[]::text[], 0, ARRAY[]::text[], 'uncommon', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 390, '{"needs_review":false}'::jsonb),
